import { useState, type HTMLAttributes, type ReactNode, type Ref } from "react";
import { Heading, LinkContext } from "react-aria-components";
import { Media } from "./Media";
import { Text } from "./Text";
import "./Card.css";

type CardSize = "small" | "medium" | "large";
type CardVariant = "flat" | "raised" | "sunken";

export interface CardProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /**
   * `flat` (default) sits in the document flow. `raised` is for a card that genuinely floats —
   * a sticky bar — and adds the elevation Toolbar's floating variant uses.
   * `sunken` sets the panel into the page: the sunken surface fill and no outline, for a summary or
   * a grouped readout inside a flat section.
   *
   * @default "flat"
   */
  variant?: CardVariant;
  /**
   * Surface tier — drives padding and radius together, so an inset child stays concentric.
   * `small` suits compact chrome (a bar, a row); `large` a spacious panel.
   *
   * @default "medium"
   */
  size?: CardSize;
  /**
   * Marks the one card a list highlights: its edge takes the brand's line, never a deeper shadow.
   * Pair it with a `CardRibbon` saying why.
   *
   * @default false
   */
  isFeatured?: boolean;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

type CardRibbonVariant = "tonal" | "primary";

export interface CardRibbonProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /**
   * Badge's words for the same mark. `tonal` (default) is the band on the brand's tint, for a
   * dense list; `primary` the brand solid, the loud recommendation band over a card.
   *
   * @default "tonal"
   */
  variant?: CardRibbonVariant;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export interface CardMediaProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /**
   * The band must contrast with the ground the CARD sits on. `well` (default) runs the neutral
   * plate edge to edge, for a card on a white page; `plain` paints no band, for a card on a grey
   * band, where the cut-out sits contained on the card's own white surface.
   *
   * @default "well"
   */
  variant?: "well" | "plain";
  /** A line under the picture, inside the band: what the picture shows, centred and muted. */
  caption?: ReactNode;
  /**
   * A mark laid over the picture at its bottom-start corner, one card padding in from each edge
   * and above the caption, never on it, e.g. `<Badge>Comparing deals</Badge>`. It is a status, not
   * a control: presses pass through it to the picture, or to the action area the band sits in.
   */
  overlay?: ReactNode;
  /** The picture, sized by the `AspectRatio` it sits in, e.g.
   *  `<AspectRatio ratio={4 / 3}><img … /></AspectRatio>`. */
  children?: ReactNode;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export interface CardActionAreaProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export interface CardHeaderProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export interface CardTitleProps extends Omit<HTMLAttributes<HTMLHeadingElement>, "className"> {
  /**
   * Heading level, so the card can sit at the right depth in the page outline. The default is the
   * level this used to hardcode, so existing usage is unchanged.
   *
   * @default 3
   */
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
  className?: string;
  ref?: Ref<HTMLHeadingElement>;
}

export interface CardDescriptionProps extends Omit<HTMLAttributes<HTMLParagraphElement>, "className"> {
  className?: string;
  ref?: Ref<HTMLParagraphElement>;
}

export interface CardContentProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export interface CardFooterProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /**
   * Closes the card edge to edge: the rule runs across the card's full width and the footer's own
   * content meets it and the card's bottom with no padding of the card's, for a row that brings its
   * own height (a full-width disclosure trigger).
   *
   * @default false
   */
  isFlush?: boolean;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

function mergeClassName(base: string, className?: string) {
  return className ? `${base} ${className}` : base;
}

export function Card({
  variant = "flat",
  size = "medium",
  isFeatured = false,
  className,
  ...props
}: CardProps) {
  return (
    <div
      {...props}
      data-size={size}
      data-variant={variant}
      data-featured={isFeatured || undefined}
      className={mergeClassName("sd-card", className)}
    />
  );
}

/** A band across the card's top, edge to edge, clipped by the card's corners: the reason a card is
 *  featured ("Our pick"). Place it as the card's first child. */
export function CardRibbon({ variant = "tonal", className, ...props }: CardRibbonProps) {
  return (
    <div
      {...props}
      data-variant={variant}
      // CONTRASTIVE: the Badge role, one rung below the card's content, as a ribbon labels the card rather than reading as part of it.
      className={mergeClassName("sd-card__ribbon sd-type-caption-small-emphasized", className)}
    />
  );
}

/** A picture as a band across the card, edge to edge: the card's top when it is the first child,
 *  on Media's `well` plate run full width, with an optional caption inside the band. */
export function CardMedia({ variant = "well", caption, overlay, children, className, ...props }: CardMediaProps) {
  return (
    <div {...props} data-variant={variant} className={mergeClassName("sd-card__media", className)}>
      {/* The band owns the corner, so the picture inside it sits flush. `contain` either way: a
          cut-out is shown whole, on the plate or on the card's surface. */}
      <Media variant={variant} fit="contain" isFlush className="sd-card__media-picture">
        {children}
      </Media>
      {overlay && <div className="sd-card__media-overlay">{overlay}</div>}
      {caption && (
        <Text variant="caption" size="small" tone="muted" className="sd-card__media-caption">
          {caption}
        </Text>
      )}
    </div>
  );
}

/* The press target of a card that holds more than one control: the stretched-link pattern, so no
   interactive element nests in another. The one `Link` inside takes `sd-card__link` through React
   Aria's `LinkContext` (the slot mechanism, as `TextContext` hands Button its label class), and its
   `::after` stretches over this area. Hover and press land on the Link, not here, so the area relays
   them through the same context as `data-link-hovered` / `data-link-pressed`, and paints the
   state wash on its own layer. A `:has()` would read a descendant, which the styling rules forbid. */
/** The pressable part of a card: a full-width band holding ONE `Link`, whose press covers the whole
 *  band and whose hover and press wash it. Other controls stay outside it. */
export function CardActionArea({ className, children, ...props }: CardActionAreaProps) {
  const [isHovered, setHovered] = useState(false);
  const [isPressed, setPressed] = useState(false);
  return (
    <div
      {...props}
      data-link-hovered={isHovered || undefined}
      data-link-pressed={isPressed || undefined}
      className={mergeClassName("sd-card__action-area", className)}
    >
      {/* Press start and end, not `onPressChange`: React Aria's `useLink` forwards only these two
          of the press handlers. */}
      <LinkContext.Provider
        value={{
          className: "sd-card__link",
          onHoverChange: setHovered,
          onPressStart: () => setPressed(true),
          onPressEnd: () => setPressed(false),
        }}
      >
        {children}
      </LinkContext.Provider>
    </div>
  );
}

export function CardHeader({ className, ...props }: CardHeaderProps) {
  return <div {...props} className={mergeClassName("sd-card__header", className)} />;
}

/* React Aria's `Heading` rather than a bare `h3`: a card's depth in the document outline depends on
   where the page puts it, and a hardcoded level breaks the outline the moment a card is nested under
   anything but an h2. Same primitive AccordionItem and DialogTitle already use.
   Safe standalone AND inside a Dialog — RAC's Dialog provides a HeadingContext whose slots include a
   `DEFAULT_SLOT: {}` entry, so an unslotted Heading resolves to `{}` instead of throwing the
   "A slot prop is required" error, and it does not inherit the dialog title's `level: 2`
   (verified against node_modules/react-aria-components/dist/private/{Heading,Dialog}.mjs). */
export function CardTitle({ headingLevel = 3, className, ...props }: CardTitleProps) {
  return (
    <Heading
      {...props}
      level={headingLevel}
      className={mergeClassName("sd-card__title sd-type-title-medium", className)}
    />
  );
}

export function CardDescription({ className, ...props }: CardDescriptionProps) {
  return (
    <p
      {...props}
      className={mergeClassName("sd-card__description sd-type-caption-medium", className)}
    />
  );
}

export function CardContent({ className, ...props }: CardContentProps) {
  return (
    <div {...props} className={mergeClassName("sd-card__content sd-type-body-medium", className)} />
  );
}

export function CardFooter({ isFlush = false, className, ...props }: CardFooterProps) {
  return (
    <div
      {...props}
      data-flush={isFlush || undefined}
      className={mergeClassName("sd-card__footer", className)}
    />
  );
}

/* Card is this library's neutral surface — the only component that owns "elevated paper" chrome for
   arbitrary content, because Blocks own no Cmp tokens and Layout primitives own no look, so nothing
   else is *allowed* to paint one. Hence two axes:
   `size`    — the paired Sys surface tier (padding + radius together), so each brand preserves its
               intended concentric relationship whichever size is used.
   `variant` — `flat` (default) sits in the document flow; `raised` is persistent floating chrome
               (a sticky bar). Same shape as Toolbar's flat/raised. */
.sd-card {
  display: flex;
  flex-direction: column;
  background: var(--sd-card-background);
  color: var(--sd-card-foreground);
  border: var(--sd-card-border-width) solid var(--sd-card-border);
  /* The description's ink, relayed so a washed action area can raise it (§6.5). */
  --sd-card-description-foreground-current: var(--sd-card-description-foreground);
}

/* The footer's inset, and the padding the full-bleed parts (ribbon, action area, flush
   footer) cancel, are set on a CHILD from the root's `data-size`, so it travels through a
   `-current` local intermediate rather than a descendant combinator (§6.5). */
.sd-card[data-size="small"] {
  gap: var(--sd-card-gap-small);
  padding: var(--sd-card-padding-small);
  border-radius: var(--sd-card-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
  --sd-card-footer-padding-block-start-current: var(--sd-card-footer-padding-block-start-small);
  --sd-card-padding-current: var(--sd-card-padding-small);
}
.sd-card[data-size="medium"] {
  gap: var(--sd-card-gap-medium);
  padding: var(--sd-card-padding-medium);
  border-radius: var(--sd-card-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
  --sd-card-footer-padding-block-start-current: var(--sd-card-footer-padding-block-start-medium);
  --sd-card-padding-current: var(--sd-card-padding-medium);
}
.sd-card[data-size="large"] {
  gap: var(--sd-card-gap-large);
  padding: var(--sd-card-padding-large);
  border-radius: var(--sd-card-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
  --sd-card-footer-padding-block-start-current: var(--sd-card-footer-padding-block-start-large);
  --sd-card-padding-current: var(--sd-card-padding-large);
}

/* flat (default) casts only the brand's resting shadow (`shadow.rest`: none in most brands, a low lift
   in one): the border + the `surface.raised` background already carry the boundary, and a full
   elevation put an in-flow card at modal height. `raised` is the opt-in for a
   card that genuinely floats — `elevation.medium`, matching Toolbar's floating control bar, one tier
   below the overlay layer (`elevation.high` = Dialog · Drawer · Popover · Tooltip · Toast). */
.sd-card[data-variant="flat"] {
  box-shadow: var(--sd-card-shadow);
}

.sd-card[data-variant="raised"] {
  box-shadow: var(--sd-card-shadow-raised);
}

/* sunken: set into the page rather than on it. The border takes the fill so the box keeps a flat
   card's size and the inset content does not shift between variants. */
.sd-card[data-variant="sunken"] {
  background: var(--sd-card-background-sunken);
  border-color: var(--sd-card-border-sunken);
}

/* isFeatured: only the edge's colour moves, so a featured card keeps its neighbours' size. */
.sd-card[data-featured] {
  border-color: var(--sd-card-border-featured);
}

/* Full-bleed parts. Each cancels the card's padding with a negative margin and pads itself back by
   the same amount, so its paint runs to the card's inner edge while its content keeps the card's
   column. A corner it touches inherits that corner of the card (each longhand inherits its own
   corner, so the inner corners stay square), so the paint follows the card's curve without clipping
   the card: an `overflow` on every card would cut what consumers let overhang it. */
.sd-card__ribbon {
  margin-block-start: calc(-1 * var(--sd-card-padding-current));
  margin-inline: calc(-1 * var(--sd-card-padding-current));
  padding-block: var(--sd-card-ribbon-padding-block);
  /* The ribbon's text is the card's own text, so it stands where the title does: the card padding
     plus the text inset (component-contract.md §6 rule 8). */
  padding-inline: calc(var(--sd-card-padding-current) + var(--sd-card-text-padding-inline));
  border-start-start-radius: inherit;
  border-start-end-radius: inherit;
  corner-shape: inherit;
}
.sd-card__ribbon[data-variant="tonal"] {
  background: var(--sd-card-ribbon-background-tonal);
  color: var(--sd-card-ribbon-foreground-tonal);
}
.sd-card__ribbon[data-variant="primary"] {
  background: var(--sd-card-ribbon-background-primary);
  color: var(--sd-card-ribbon-foreground-primary);
}

/* The media band runs edge to edge (on the well's plate unless `plain`). At the card's top (its first child) it
   takes the card's top padding back and inherits the card's top corners, and it clips the flush
   picture to them; anywhere else it is a square band after the card's gap. */
.sd-card__media {
  /* One column: the picture's row, the overlay laid in that same cell, and the caption's row under
     it, so the overlay stands on the picture and never on the caption. */
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  margin-inline: calc(-1 * var(--sd-card-padding-current));
  overflow: clip;
}
/* well: the plate, for a card on a white page. `plain` paints none: on a grey band the card's own
   surface is the contrast. */
.sd-card__media[data-variant="well"] {
  background: var(--sd-card-media-background);
}
.sd-card__media:first-child {
  margin-block-start: calc(-1 * var(--sd-card-padding-current));
  border-start-start-radius: inherit;
  border-start-end-radius: inherit;
  corner-shape: inherit;
}
/* The overlay sits one card padding in from the picture's bottom and start edges (the tag about a
   picture stands ON it, bottom-start), so a Badge on the picture stands on the card's own box line.
   It shares the picture's grid cell, sized by its content and inside the band's clip, and it takes
   no pointer, so the picture or the action area under it keeps every press. */
/* The picture and the overlay share the first cell; the caption flows into the row under it. */
.sd-card__media-picture {
  grid-area: 1 / 1;
}
.sd-card__media-overlay {
  grid-area: 1 / 1;
  align-self: end;
  justify-self: start;
  z-index: 1;
  margin: var(--sd-card-padding-current);
  max-inline-size: calc(100% - 2 * var(--sd-card-padding-current));
  display: flex;
  pointer-events: none;
}
.sd-card__media-caption {
  margin: 0;
  padding-block: var(--sd-card-media-caption-padding-block);
  /* The card's own text column: the card padding plus the text inset (§6 rule 8). */
  padding-inline: calc(var(--sd-card-padding-current) + var(--sd-card-text-padding-inline));
  text-align: center;
}

/* The action area is a band: it reaches the card's inline edges and takes the seams above and
   below it into its own padding, so the wash covers the whole press target and the next part meets
   it directly. One relay serves both seams because the card's gap IS its padding at every size
   (`card.gap.<size>` aliases `card.padding.<size>`). The stretched link's `::after` is positioned
   against this box; `isolation` keeps the wash layer under the content and over the card's fill. */
.sd-card__action-area {
  position: relative;
  isolation: isolate;
  /* The card's own column inside the band, so its parts keep the card's rhythm. */
  display: flex;
  flex-direction: column;
  gap: var(--sd-card-padding-current);
  margin: calc(-1 * var(--sd-card-padding-current));
  padding: var(--sd-card-padding-current);
}
.sd-card__action-area:first-child {
  border-start-start-radius: inherit;
  border-start-end-radius: inherit;
  corner-shape: inherit;
}
.sd-card__action-area:last-child {
  border-end-start-radius: inherit;
  border-end-end-radius: inherit;
  corner-shape: inherit;
}
.sd-card__action-area::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-card__action-area[data-link-hovered]::after {
  background: var(--sd-state-hover);
}
.sd-card__action-area[data-link-pressed]::after {
  background: var(--sd-state-pressed);
}
/* Text over the wash rises to the default ink while it is washed (component-contract.md §6 rule 7):
   only `text.DEFAULT` holds its floor over the surface wash. The area holds text it does not own,
   so it re-points every non-default text role its descendants can read, at each layer they read it:
   - Card's own description, through its relay;
   - `Text`'s tones, Cmp aliases that resolved at the root and so must be re-declared here;
   - the Sys text roles a Block inks its own parts with (block-contract.md §5), read directly.
   Each takes the card's own ink, which already follows an inverse ground. */
.sd-card__action-area[data-link-hovered],
.sd-card__action-area[data-link-pressed] {
  --sd-card-description-foreground-current: var(--sd-card-foreground);
  --sd-text-muted-foreground: var(--sd-card-foreground);
  --sd-text-emphasis-foreground: var(--sd-card-foreground);
  --sd-text-urgency-foreground: var(--sd-card-foreground);
  --sd-color-text-muted: var(--sd-card-foreground);
  --sd-color-text-brand: var(--sd-card-foreground);
  --sd-color-text-emphasis: var(--sd-card-foreground);
  --sd-color-text-urgency: var(--sd-card-foreground);
}

/* The one Link in an action area, given this class through React Aria's LinkContext: its own box
   stays where its text is (and keeps its focus ring there), and its `::after` covers the area, so a
   press anywhere on the band is a press on the link. */
.sd-card__link::after {
  content: "";
  position: absolute;
  inset: 0;
}

.sd-card__header {
  display: flex;
  flex-direction: column;
  gap: var(--sd-card-header-gap);
}

.sd-card__title {
  margin: 0;
  color: var(--sd-card-title-foreground);
  /* Text the card always draws on its own surface takes the text inset (component-contract.md §6
     rule 8, component-owned text). On the parts, so a Button or Badge in the header stays at the
     card padding. Inline only: `text-inset.block` is spent by no part. */
  padding-inline: var(--sd-card-text-padding-inline);
}

.sd-card__description {
  margin: 0;
  color: var(--sd-card-description-foreground-current);
  padding-inline: var(--sd-card-text-padding-inline);
}

.sd-card__content {
  color: var(--sd-card-content-foreground);
  /* A region, not a line of text: its role class lends the font to what it holds and must not
     pad it, or every box inside moves one text inset in. Text placed here carries its own role. */
  padding-inline: 0;
}

.sd-card__footer {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sd-card-footer-gap);
  align-items: center;
  padding-block-start: var(--sd-card-footer-padding-block-start-current);
  border-block-start: var(--sd-card-border-width) solid var(--sd-card-border);
}

/* isFlush: the footer runs edge to edge and closes the card. Its rule spans the full width, its
   content meets the rule with no inset, and it takes the card's bottom padding back, so a row that
   brings its own height (a disclosure trigger) is what ends the card. */
.sd-card__footer[data-flush] {
  margin-inline: calc(-1 * var(--sd-card-padding-current));
  margin-block-end: calc(-1 * var(--sd-card-padding-current));
  padding-inline: var(--sd-card-padding-current);
  padding-block-start: 0;
}
